/* Standalone design prototype. All settings, devices, and actions are local samples. */
"use strict";
const profiles = [
  {id:"immediate",name:"Immediate",icon:"↗",description:"Notify once, including overnight."},
  {id:"ack",name:"Immediate — acknowledgement required",icon:"↗",description:"Notify including overnight. Repeat until acknowledged or resolved."},
  {id:"morning",name:"Morning summary",icon:"☀",description:"Include in the next morning report."},
  {id:"evening",name:"Evening summary",icon:"☾",description:"Include in the next evening report."},
  {id:"weekly",name:"Weekly summary",icon:"▦",description:"Include on the chosen weekday and time."}
];
const people = {michael:{name:"Michael",initials:"MC",role:"Administrator",routes:["iPhone","iPad"]},sarah:{name:"Sarah",initials:"SC",role:"Household member",routes:["Pixel"]}};
const devices = [
  {id:"leak",name:"Basement leak detector",group:"Zigbee",place:"Basement",watched:true,conditions:[{id:"availability",name:"Monitoring becomes unavailable"},{id:"water",name:"Water is detected",situation:true}]},
  {id:"door",name:"Front door contact",group:"Zigbee",place:"Entry",watched:true,conditions:[{id:"availability",name:"Monitoring becomes unavailable"}]},
  {id:"hall",name:"Hallway motion sensor",group:"Zigbee",place:"Hallway",watched:true,conditions:[{id:"availability",name:"Monitoring becomes unavailable"}]},
  {id:"freezer",name:"Freezer temperature sensor",group:"Wi-Fi",place:"Garage",watched:true,conditions:[{id:"availability",name:"Monitoring becomes unavailable"}]},
  {id:"speakers",name:"Outdoor speakers",group:"Wi-Fi",place:"Backyard",watched:true,conditions:[{id:"availability",name:"Monitoring becomes unavailable"}]},
  {id:"garden",name:"Garden lights",group:"Wi-Fi",place:"Garden",watched:false,conditions:[{id:"availability",name:"Monitoring becomes unavailable"}]}
];
const clone = value => structuredClone(value);
const esc = value => String(value).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const nameOf = id => profiles.find(p=>p.id===id)?.name || (id==="off"?"Dashboard only":"Use default");
const initial = () => ({revision:1,enabled:false,timezone:"America/Chicago",household:"morning",custom:false,
  people:{michael:["iPhone"],sarah:["Pixel"]},
  profiles:{immediate:{to:["michael"]},ack:{to:["michael","sarah"],reminder:"30"},morning:{to:["michael"],time:"08:00"},evening:{to:["michael"],time:"18:00"},weekly:{to:["michael"],time:"09:00",day:"Sunday"}},
  devices:{leak:{base:"immediate",conditions:{availability:"inherit",water:"ack"}},door:{base:"inherit",conditions:{availability:"inherit"}},hall:{base:"inherit",conditions:{availability:"inherit"}},freezer:{base:"immediate",conditions:{availability:"inherit"}},speakers:{base:"weekly",conditions:{availability:"inherit"}},garden:{base:"weekly",conditions:{availability:"inherit"}}}
});
let saved=initial(), draft=clone(saved), page="notifications", selected="leak", sourceTab="settings", openProfile=null, openPerson=null, query="", selectedBulk=new Set(), collapsed=new Set(), mobileDetail=false, scenario="normal", staleTriggered=false, chooser=null, reviewRevision=0, reviewDraft=null, reviewReturn=null, toastTimer;
const app=document.querySelector("#app"), review=document.querySelector("#review"), picker=document.querySelector("#picker");
const timeLabel = time => {if(!time)return "Choose a time";const [h,m]=time.split(":").map(Number);return `${h%12||12}:${String(m).padStart(2,"0")} ${h<12?"AM":"PM"}`;};
const recipients = ids => ids.map(id=>people[id].name).join(", ") || "No recipients selected";
function timing(config,id){const p=config.profiles[id];return id==="weekly"?`${p.day}, ${timeLabel(p.time)}`:["morning","evening"].includes(id)?timeLabel(p.time):"Any time";}
function effective(config,deviceId,conditionId){const d=config.devices[deviceId];return d.conditions[conditionId]!=="inherit"?d.conditions[conditionId]:d.base!=="inherit"?d.base:config.household;}
function assignmentCount(config,profile){return devices.filter(d=>d.watched).reduce((n,d)=>n+d.conditions.filter(c=>effective(config,d.id,c.id)===profile).length,0);}
function origin(config,id,condition){const d=config.devices[id];return d.conditions[condition]!=="inherit"?"Condition exception":d.base!=="inherit"?`Uses device preference: ${nameOf(d.base)}`:`Uses household default: ${nameOf(config.household)}`;}
function explanation(config,id){if(id==="off")return "Shown on the dashboard. No notification or report.";const p=config.profiles[id];const schedule=id==="weekly"?`${p.day} at ${timeLabel(p.time)}`:["morning","evening"].includes(id)?`daily at ${timeLabel(p.time)}`:"including overnight";return `${recipients(p.to)} · ${schedule}${id==="ack"?` · repeats every ${p.reminder} minutes until acknowledged or resolved`:""}.`;}
function issues(config){const result=[];for(const p of profiles){if(!config.profiles[p.id].to.length)result.push(`Choose who receives ${p.name.toLowerCase()}.`);for(const id of config.profiles[p.id].to){if(!config.people[id].length)result.push(`Choose a destination for ${people[id].name}.`);}if(["morning","evening","weekly"].includes(p.id)&&!/^\d{2}:\d{2}$/.test(config.profiles[p.id].time))result.push(`Choose a time for ${p.name.toLowerCase()}.`);}return [...new Set(result)];}
function changes(){const rows=[];const add=(name,before,after,scope="")=>{if(before!==after)rows.push({name,before,after,scope});};
  add("Notification requests",saved.enabled?"On":"Off",draft.enabled?"On":"Off",draft.enabled?"Sample activation only. No messages are sent by this prototype.":"");
  add("Time zone",saved.timezone,draft.timezone,"Applies to all three report schedules.");
  add("Household default",nameOf(saved.household),nameOf(draft.household),`${devices.filter(d=>d.watched).reduce((n,d)=>n+d.conditions.filter(c=>saved.devices[d.id].base==="inherit"&&saved.devices[d.id].conditions[c.id]==="inherit").length,0)} monitored condition assignments currently inherit this default.`);
  for(const p of profiles){const count=assignmentCount(saved,p.id),scope=`${count} monitored condition assignment${count===1?"":"s"} currently use${count===1?"s":""} this choice.`;add(`${p.name}: timing`,timing(saved,p.id),timing(draft,p.id),scope);add(`${p.name}: recipients`,recipients(saved.profiles[p.id].to),recipients(draft.profiles[p.id].to),scope);}
  add("Acknowledgement reminders",`${saved.profiles.ack.reminder} minutes`,`${draft.profiles.ack.reminder} minutes`);
  for(const [id,p] of Object.entries(people))add(`${p.name}: destinations`,saved.people[id].join(", ")||"None",draft.people[id].join(", ")||"None");
  for(const device of devices){const id=device.id,defaultName=(config)=>config.devices[id].base==="inherit"?`Household default (${nameOf(config.household)})`:nameOf(config.devices[id].base);if(saved.devices[id].base!==draft.devices[id].base)add(`${device.name}: device preference`,defaultName(saved),defaultName(draft),`Applies to conditions using the device preference.${Object.values(draft.devices[id].conditions).some(v=>v!=="inherit")?" Explicit condition exceptions are preserved.":""}${!device.watched?" This device remains unmonitored.":""}`);
    for(const c of device.conditions){if(saved.devices[id].conditions[c.id]!==draft.devices[id].conditions[c.id])add(`${device.name}: ${c.name.toLowerCase()}`,`${saved.devices[id].conditions[c.id]==="inherit"?"Use default: ":""}${nameOf(effective(saved,id,c.id))}`,`${draft.devices[id].conditions[c.id]==="inherit"?"Use default: ":""}${nameOf(effective(draft,id,c.id))}`,!device.watched?"Monitoring remains off.":"");}}
  return rows;
}
function notify(message){const toast=document.querySelector("#toast");toast.textContent=message;toast.classList.add("show");clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove("show"),5500);}
function captureFocus(){const node=document.activeElement;return node?.id?{id:node.id,start:node.selectionStart,end:node.selectionEnd}:null;}
function restoreFocus(info){if(!info)return;const node=document.getElementById(info.id);node?.focus({preventScroll:true});if(node?.type==="search"&&info.start!==null)node.setSelectionRange(info.start,info.end);}
function render(){const focus=captureFocus();document.querySelectorAll("[data-page]").forEach(b=>{b.classList.toggle("active",b.dataset.page===page);b.setAttribute("aria-current",b.dataset.page===page?"page":"false");});document.querySelector("#saved-state").textContent=`Saved requests: ${saved.enabled?"on":"off"}`;app.innerHTML=page==="notifications"?notificationsView():sourcesView();const dirty=changes().length;document.querySelector("#savebar").innerHTML=`<div class="save-copy"><strong>${dirty?`${dirty} unsaved change${dirty===1?"":"s"}`:"All sample settings saved"}</strong><small>${dirty?"Changes are kept as you switch pages.":"Prototype only. Nothing is sent to your home."}</small></div><div class="save-actions">${dirty?'<button class="link discard" data-action="discard">Discard</button>':""}<button id="review-button" class="primary" data-action="review" ${!dirty||saved.custom?"disabled":""}>Review changes</button></div>`;restoreFocus(focus);}
function notificationsView(){if(saved.custom)return customView();const errors=issues(draft);return `<div class="page-head"><div><h1>Notifications</h1><p class="muted">Choose when you hear about problems and who receives them.</p></div><span class="tag ${changes().length?"draft":""}">${changes().length?"Draft changes":"Saved settings"}</span></div>${errors.length?`<div class="warning"><strong>Delivery setup needs attention</strong><p>${errors.map(esc).join(" ")}</p><button class="link" data-action="people">Review destinations</button></div>`:""}<section class="section"><div class="section-title"><h2>Reporting choices</h2><p class="muted">Assign these choices to devices in Sources.</p></div><div class="profile-heading"><span>Reporting choice</span><span>When</span><span>Send to</span><span></span></div>${profiles.map(p=>profileRow(p)).join("")}<div class="inline-note"><span aria-hidden="true">↗</span><span>Both immediate choices include overnight. Acknowledgement stops reminders, not the problem.</span></div><div class="zone"><label class="field" for="timezone">Time zone<select id="timezone" data-field="timezone">${["America/Chicago","America/New_York","America/Denver","America/Los_Angeles","Australia/Sydney"].map(z=>`<option ${draft.timezone===z?"selected":""}>${z}</option>`).join("")}</select></label></div></section><section class="section" id="people-section"><div class="section-title"><h2>People and destinations</h2><p class="muted">Choose each person's destinations once, then use them above.</p></div>${Object.entries(people).map(([id,p])=>`<div class="people-row"><div class="avatar" aria-hidden="true">${p.initials}</div><div class="person-copy"><strong>${p.name}</strong><small>${draft.people[id].length?esc(draft.people[id].join(", ")):"No destination selected"}</small></div><button id="person-${id}" class="small" data-person="${id}" aria-expanded="${openPerson===id}" aria-label="Edit ${p.name}'s destinations">${openPerson===id?"Done":"Edit"}</button><button class="small" data-test="${id}" ${!draft.people[id].length?"disabled":""}>Simulate test</button></div>${openPerson===id?`<div class="person-editor"><p class="muted">Sample destinations for ${p.name}</p>${p.routes.map(route=>`<label class="check"><input id="route-${id}-${route}" type="checkbox" data-person-route="${id}" data-route="${route}" ${draft.people[id].includes(route)?"checked":""}>${route}</label>`).join("")}</div>`:""}`).join("")}</section><section class="section"><div class="settings-default"><div><h2>Household default</h2><p class="muted">Proposed: used when a device has no explicit preference.</p></div><button class="choice-button" style="width:auto" data-choose="household" id="choose-household">${nameOf(draft.household)} <span aria-hidden="true">⌄</span></button></div></section><section class="section"><div class="enable-row"><label class="check"><input type="checkbox" id="enabled" data-field="enabled" ${draft.enabled?"checked":""}>Enable notification requests</label><p class="muted">${draft.enabled!==saved.enabled?"Draft change. Review and save to apply in the prototype.":saved.enabled?"Enabled in this prototype only. No messages are sent.":"Currently off. You can configure everything before enabling requests."}</p></div></section>`;}
function profileRow(p){const config=draft.profiles[p.id],count=assignmentCount(draft,p.id);return `<div class="profile-row"><div class="profile-name"><span class="profile-icon" aria-hidden="true">${p.icon}</span><span>${p.name}<small>${count} monitored assignment${count===1?"":"s"}</small></span></div><div class="timing"><span class="cell-label">When: </span>${timing(draft,p.id)}${["immediate","ack"].includes(p.id)?"<small>Includes overnight</small>":""}</div><div class="audience"><span class="cell-label">To: </span>${recipients(config.to)}</div><button id="edit-profile-${p.id}" class="link" data-profile="${p.id}" aria-label="Edit ${p.name}" aria-expanded="${openProfile===p.id}">${openProfile===p.id?"Close":"Edit"}</button></div>${openProfile===p.id?profileEditor(p):""}`;}
function profileEditor(p){const c=draft.profiles[p.id];return `<div class="profile-editor"><div class="editor-grid">${p.id==="weekly"?`<label class="field">Day<select data-profile-field="weekly" data-key="day" id="weekly-day">${["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"].map(day=>`<option ${c.day===day?"selected":""}>${day}</option>`).join("")}</select></label>`:""}${["morning","evening","weekly"].includes(p.id)?`<label class="field">Report time<input type="time" id="${p.id}-time" data-profile-field="${p.id}" data-key="time" value="${c.time}" required></label>`:""}${p.id==="ack"?`<label class="field">Repeat every<select id="ack-reminder" data-profile-field="ack" data-key="reminder">${["15","30","60"].map(n=>`<option value="${n}" ${c.reminder===n?"selected":""}>${n} minutes</option>`).join("")}</select><small>Example interval; default not settled.</small></label>`:""}<fieldset class="recipients"><legend>Send to</legend>${Object.entries(people).map(([id,person])=>`<label class="check"><input type="checkbox" id="recipient-${p.id}-${id}" data-recipient-profile="${p.id}" data-person-id="${id}" ${c.to.includes(id)?"checked":""}>${person.name}<small>${draft.people[id].join(", ")||"No destination"}</small></label>`).join("")}</fieldset></div><p class="muted" style="margin:16px 0 0">${p.description} ${assignmentCount(draft,p.id)} monitored condition assignment${assignmentCount(draft,p.id)===1?" uses":"s use"} this choice.</p><div class="editor-actions"><button class="small" data-profile="${p.id}">Done editing</button></div></div>`;}
function customView(){return `<div class="page-head"><div><h1>Notifications</h1><p class="muted">This sample installation uses an existing custom policy.</p></div></div><section class="section custom-policy"><div class="section-title"><h2>Custom policy</h2><p class="muted">These rules cannot be represented accurately by the five reporting choices.</p></div><div style="padding:0 24px 24px"><div class="notice">Your existing recipients, routes, and quiet-hour behavior are preserved. Nothing has been converted.</div><dl class="source-facts"><div><dt>Recipients</dt><dd>Michael through a custom notification route</dd></div><div><dt>Existing behavior</dt><dd>Normal notifications wait until quiet hours end. Urgent notifications bypass them.</dd></div><div><dt>Moving to reporting choices</dt><dd>Requires a migration preview that explains overnight delivery, recipients, and existing problems. That workflow is not part of this prototype.</dd></div></dl><p class="muted" style="margin-top:20px">Choose Standard setup under Try a scenario to return to the editable sample.</p></div></section>`;}
function sourcesView(){if(saved.custom)return `<div class="page-head"><div><h1>Sources</h1><p class="muted">Reporting is controlled by the existing custom policy.</p></div></div><div class="notice">Keep current assignments until a migration is reviewed. <button class="link" data-page="notifications">View notification policy</button></div>`;return `<div class="page-head"><div><h1>Sources</h1><p class="muted">Choose what you monitor and how you hear about it.</p></div><span class="tag">Sample household</span></div><div class="sources-layout ${mobileDetail?"detail-open":""}"><aside class="source-browser" aria-label="Device browser"><div class="search"><label class="sr-only" for="search" style="display:none">Search devices</label><input id="search" type="search" placeholder="Search devices" aria-label="Search devices" value="${esc(query)}"></div><div class="browser-toolbar"><span>Grouped by integration</span><button class="link small" data-action="clear-selection" ${!selectedBulk.size?"disabled":""}>Clear</button></div>${selectedBulk.size?`<div class="bulk-bar"><p>${selectedBulk.size} device${selectedBulk.size===1?"":"s"} selected</p><button id="choose-bulk" data-choose="bulk">Set reporting preference</button></div>`:""}${["Zigbee","Wi-Fi"].map(group=>treeGroup(group)).join("")}${!devices.some(d=>d.name.toLowerCase().includes(query.toLowerCase()))?'<p class="empty">No matching devices.</p>':""}</aside>${sourcePanel()}</div>`;}
function treeGroup(group){const visible=devices.filter(d=>d.group===group&&d.name.toLowerCase().includes(query.toLowerCase()));if(!visible.length)return "";return `<div class="group-heading"><button data-group="${group}" aria-expanded="${!collapsed.has(group)}">${collapsed.has(group)?"▸":"▾"} ${group} <small>(${visible.length})</small></button></div>${collapsed.has(group)?"":visible.map(d=>`<div class="source-row ${selected===d.id?"active":""}"><input id="bulk-${d.id}" type="checkbox" aria-label="Select ${d.name} for bulk assignment" data-bulk="${d.id}" ${selectedBulk.has(d.id)?"checked":""}><button id="source-${d.id}" data-source="${d.id}" aria-current="${selected===d.id?"true":"false"}"><span>${d.name}</span><small>${d.watched?nameOf(effective(draft,d.id,"availability")):"Not monitored"}</small></button></div>`).join("")}`;}
function sourcePanel(){const d=devices.find(d=>d.id===selected);return `<section class="source-panel"><div class="source-panel-head"><button class="link mobile-back" data-action="back">‹ All devices</button><h2>${d.name}</h2><p class="muted">${d.place} · ${d.group}</p></div><nav class="tabs" aria-label="Selected source views">${["source","settings","history"].map(tab=>`<button id="tab-${tab}" data-source-tab="${tab}" class="${sourceTab===tab?"active":""}" aria-current="${sourceTab===tab?"page":"false"}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join("")}</nav><div class="source-content">${sourceTab==="settings"?sourceSettings(d):sourceTab==="source"?sourceOverview(d):sourceHistory(d)}</div></section>`;}
function sourceSettings(d){const base=draft.devices[d.id].base;return `<div class="monitoring-status"><div><h3>Monitoring</h3><p class="muted">Availability</p></div><span class="tag">${d.watched?"Monitored":"Not monitored"}</span></div>${!d.watched?'<div class="warning">This device is not monitored. A reporting preference does not enable monitoring.</div>':""}<h3>Reporting</h3><p class="muted">Device preference applies unless a condition has its own choice.</p><button class="choice-button" id="choose-device" data-choose="device">${base==="inherit"?`Household default: ${nameOf(draft.household)}`:nameOf(base)}<span aria-hidden="true">⌄</span></button>${d.conditions.map(c=>{const id=effective(draft,d.id,c.id);return `<div class="condition"><span class="condition-name">When ${c.name.toLowerCase()}</span><button class="choice-button" id="choose-${c.id}" data-choose="condition" data-condition="${c.id}">${nameOf(id)}<span aria-hidden="true">⌄</span></button><p class="origin">${esc(origin(draft,d.id,c.id))}</p><p>${esc(explanation(draft,id))}</p>${!draft.enabled?'<p>Notification requests are off.</p>':draft.enabled!==saved.enabled?'<p>Requests enabled in draft only.</p>':""}${c.situation?'<p>Bound to a separately configured water-detection situation.</p>':""}</div>`;}).join("")}<button class="link" data-page="notifications">Change shared schedules and recipients</button><p class="muted">Your draft stays with you when you switch pages.</p>`;}
function sourceOverview(d){return `<dl class="source-facts"><div><dt>Monitoring</dt><dd>${d.watched?"Home Assistant availability is monitored":"Not monitored"}</dd></div><div><dt>Current evidence</dt><dd>${d.watched?"Sample: selected Home Assistant entities are available.":"No monitored evidence."}</dd></div><div><dt>Availability reporting</dt><dd>${nameOf(effective(draft,d.id,"availability"))}</dd></div></dl><button class="link" data-source-tab="settings">Edit monitoring and reporting settings</button><p class="muted">Sample observations do not establish physical device health.</p>`;}
function sourceHistory(d){return `<h3>History for ${d.name}</h3><p class="muted">No recorded incidents in this sample.</p><div class="notice">Report contents are still being designed. This prototype does not simulate outage history or weekly delivery.</div>`;}
function openChooser(kind,condition){chooser={kind,condition,device:selected,ids:[...selectedBulk],returnId:document.activeElement?.id};const current=kind==="household"?draft.household:kind==="device"?draft.devices[selected].base:kind==="condition"?draft.devices[selected].conditions[condition]:null;const title=kind==="bulk"?`Reporting for ${selectedBulk.size} devices`:kind==="household"?"Household default":"Choose reporting";const inherit=kind!=="household"?`<button class="choice-option ${current==="inherit"?"selected":""}" data-choice="inherit"><span class="radio" aria-hidden="true"></span><span><strong>${kind==="condition"?"Use device preference":"Use household default"}</strong><small>${kind==="condition"?nameOf(draft.devices[selected].base==="inherit"?draft.household:draft.devices[selected].base):nameOf(draft.household)}</small></span></button>`:"";picker.innerHTML=`<div class="dialog-head"><div><h2 id="picker-title">${title}</h2><p>${kind==="bulk"?"Changes device preferences. Explicit condition exceptions stay as they are.":"Immediate always includes overnight."}</p></div><button data-action="close-picker" aria-label="Close choices">×</button></div><div class="dialog-body">${kind==="bulk"?`<p class="muted">${chooser.ids.map(id=>devices.find(d=>d.id===id).name).join(", ")}</p>`:""}${inherit}${profiles.map(p=>`<button class="choice-option ${current===p.id?"selected":""}" data-choice="${p.id}"><span class="radio" aria-hidden="true"></span><span><strong>${p.name}</strong><small>${p.description}</small></span></button>`).join("")}<button class="choice-option ${current==="off"?"selected":""}" data-choice="off"><span class="radio" aria-hidden="true"></span><span><strong>Dashboard only</strong><small>Keep monitoring. Do not send notifications or reports.</small></span></button></div>`;picker.showModal();}
function choose(value){const c=chooser;if(c.kind==="household")draft.household=value;else if(c.kind==="device")draft.devices[c.device].base=value;else if(c.kind==="condition")draft.devices[c.device].conditions[c.condition]=value;else c.ids.forEach(id=>draft.devices[id].base=value);picker.close();render();if(c.returnId)document.getElementById(c.returnId)?.focus();if(c.kind==="bulk")notify(`Draft updated for ${c.ids.length} devices. Condition exceptions preserved.`);}
function openReview(refresh=false){reviewReturn=document.activeElement;reviewRevision=saved.revision;reviewDraft=clone(draft);drawReview(false);if(!review.open)review.showModal();if(scenario==="stale"&&!staleTriggered&&!refresh){staleTriggered=true;saved.revision+=1;draft.revision=saved.revision;drawReview(true);}}
function drawReview(stale){const rows=changes(),errors=issues(draft);review.innerHTML=`<div class="dialog-head"><div><h2 id="review-title">Review changes</h2><p>${rows.length} change${rows.length===1?"":"s"} to the sample household</p></div><button data-action="close-review" aria-label="Close review">×</button></div><div class="dialog-body">${stale?'<div class="warning"><strong>This review is out of date.</strong><p>Another sample editor changed the configuration revision. Your draft is preserved. Refresh this review before saving.</p></div>':""}${errors.length?`<div class="warning"><strong>Complete the delivery setup</strong><p>${errors.map(esc).join(" ")}</p><p>Close this review to correct the draft.</p></div>`:""}${rows.map(row=>`<div class="review-change"><strong>${esc(row.name)}</strong><div class="before-after"><span>${esc(row.before)}</span><span aria-hidden="true">→</span><span>${esc(row.after)}</span></div>${row.scope?`<small>${esc(row.scope)}</small>`:""}</div>`).join("")}<p class="muted" style="margin-top:20px">Saving changes only this prototype. No household settings or notification services are connected.</p></div><div class="dialog-footer"><button data-action="close-review">Keep editing</button>${stale?'<button class="primary" data-action="refresh-review">Refresh review</button>':`<button class="primary" data-action="save" ${errors.length||!rows.length?"disabled":""}>Save sample settings</button>`}</div>`;}
function save(){if(reviewRevision!==saved.revision||JSON.stringify(reviewDraft)!==JSON.stringify(draft)){drawReview(true);return;}if(issues(draft).length)return;saved=clone(draft);saved.revision+=1;draft=clone(saved);review.close();render();notify("Sample settings saved. No notifications were sent.");}
function loadScenario(value){scenario=value;saved=initial();if(value==="missing")saved.people.michael=[];if(value==="custom")saved.custom=true;draft=clone(saved);staleTriggered=false;openProfile=null;openPerson=null;selectedBulk.clear();page="notifications";mobileDetail=false;document.querySelector(".demo-tools").open=false;render();notify(value==="stale"?"Make a change, then review it to try a stale review.":"Sample scenario loaded.");}
document.addEventListener("click",event=>{const button=event.target.closest("button");if(!button)return;const d=button.dataset;
  if(d.page){page=d.page;render();document.querySelector("h1")?.scrollIntoView({block:"start"});}
  else if(d.profile){openProfile=openProfile===d.profile?null:d.profile;render();}
  else if(d.person){openPerson=openPerson===d.person?null:d.person;render();}
  else if(d.test){notify(`Simulated test to ${people[d.test].name}: ${draft.people[d.test].join(", ")}. No message sent.`);}
  else if(d.source){selected=d.source;mobileDetail=true;render();}
  else if(d.sourceTab){sourceTab=d.sourceTab;render();}
  else if(d.group){collapsed.has(d.group)?collapsed.delete(d.group):collapsed.add(d.group);render();}
  else if(d.choose){openChooser(d.choose,d.condition);}
  else if(d.choice){choose(d.choice);}
  else if(d.scenario){loadScenario(d.scenario);}
  else if(d.action==="review")openReview();
  else if(d.action==="close-review")review.close();
  else if(d.action==="refresh-review")openReview(true);
  else if(d.action==="close-picker")picker.close();
  else if(d.action==="save")save();
  else if(d.action==="discard"){draft=clone(saved);render();notify("Draft discarded. Saved sample settings restored.");}
  else if(d.action==="clear-selection"){selectedBulk.clear();render();}
  else if(d.action==="back"){mobileDetail=false;render();}
  else if(d.action==="people"){openPerson="michael";render();document.getElementById("people-section")?.scrollIntoView({block:"center"});}
  else if(button.id==="phone"){const on=document.body.classList.toggle("phone-frame");button.setAttribute("aria-pressed",String(on));button.textContent=on?"Desktop view":"Phone view";}
  else if(button.id==="theme"){const on=document.body.classList.toggle("dark");button.setAttribute("aria-pressed",String(on));button.textContent=on?"Light theme":"Dark theme";}
});
document.addEventListener("change",event=>{const node=event.target,d=node.dataset;
  if(d.field){draft[d.field]=node.type==="checkbox"?node.checked:node.value;}
  else if(d.profileField){draft.profiles[d.profileField][d.key]=node.value;}
  else if(d.recipientProfile){const to=draft.profiles[d.recipientProfile].to;draft.profiles[d.recipientProfile].to=node.checked?[...new Set([...to,d.personId])]:to.filter(id=>id!==d.personId);}
  else if(d.personRoute){const routes=draft.people[d.personRoute];draft.people[d.personRoute]=node.checked?[...new Set([...routes,d.route])]:routes.filter(route=>route!==d.route);}
  else if(d.bulk){node.checked?selectedBulk.add(d.bulk):selectedBulk.delete(d.bulk);}
  else return;render();
});
document.addEventListener("input",event=>{if(event.target.id==="search"){query=event.target.value;render();}});
render();
